<template>
  <div class="commercial-page">
    <section class="commercial-hero alert-hero"><div><span class="eyebrow">MONITOR & RESPOND</span><h2>业务告警中心</h2><p>配置阈值规则，追踪开放、确认、恢复与抑制事件。</p></div><div class="commercial-stats"><span><strong>{{ rules.filter(item=>item.status==='ACTIVE').length }}</strong><small>有效规则</small></span><span><strong>{{ events.filter(item=>item.status==='OPEN').length }}</strong><small>待处理</small></span><span><strong>{{ events.filter(item=>item.status==='SUPPRESSED').length }}</strong><small>已抑制</small></span></div></section>
    <UnifiedState v-if="loading" state="loading" description="正在加载告警规则和事件。" />
    <UnifiedState v-else-if="error" state="error" :description="error" retryable @retry="load" />
    <section v-else class="commercial-card"><header><el-segmented v-model="tab" :options="[{label:'告警规则',value:'rules'},{label:'事件列表',value:'events'}]" /><el-button v-if="tab==='rules'" type="primary" @click="newRule">新建规则</el-button></header>
      <el-table v-if="tab==='rules'" :data="rules" stripe empty-text="尚未配置告警规则"><el-table-column prop="name" label="规则名称" min-width="220" /><el-table-column prop="workspaceId" label="工作空间" width="120" /><el-table-column label="条件" min-width="160"><template #default="{row}">{{ operatorLabel(row.operator) }} {{ row.threshold }}</template></el-table-column><el-table-column prop="suppressionSeconds" label="抑制窗口" width="130"><template #default="{row}">{{ formatDuration(row.suppressionSeconds) }}</template></el-table-column><el-table-column label="负责人" min-width="150"><template #default="{row}">{{ memberName(row.ownerMemberId) }}</template></el-table-column><el-table-column label="状态" width="110"><template #default="{row}"><el-tag :type="row.status==='ACTIVE'?'success':'info'">{{ row.status }}</el-tag></template></el-table-column><el-table-column label="操作" width="180" align="right"><template #default="{row}"><el-button text type="primary" :disabled="row.ownerMemberId!==app.currentMember?.id" @click="editRule(row)">编辑</el-button><el-button text :type="row.status==='ACTIVE'?'danger':'success'" :disabled="row.ownerMemberId!==app.currentMember?.id" @click="toggleRule(row)">{{row.status==='ACTIVE'?'停用':'启用'}}</el-button></template></el-table-column></el-table>
      <el-table v-else :data="events" stripe empty-text="当前没有告警事件"><el-table-column prop="id" label="事件 ID" width="105" /><el-table-column label="规则" min-width="210"><template #default="{row}">{{ ruleName(row.ruleId) }}</template></el-table-column><el-table-column prop="actualValue" label="实际值" width="120" /><el-table-column label="状态" width="130"><template #default="{row}"><el-tag :type="eventTone(row.status)">{{ eventLabel(row.status) }}</el-tag></template></el-table-column><el-table-column prop="occurredAt" label="发生时间" min-width="175"><template #default="{row}">{{ formatTime(row.occurredAt) }}</template></el-table-column><el-table-column prop="acknowledgedAt" label="确认时间" min-width="175"><template #default="{row}">{{ row.acknowledgedAt?formatTime(row.acknowledgedAt):'—' }}</template></el-table-column><el-table-column label="操作" width="170" align="right"><template #default="{row}"><el-button text type="primary" @click="showEvent(row)">详情</el-button><el-button v-if="row.status==='OPEN'" text type="warning" @click="ack(row)">确认</el-button></template></el-table-column></el-table>
    </section>
    <CommonDialog v-model="ruleOpen" :title="editingRule?'编辑告警规则':'新建告警规则'" width="620px"><el-form label-position="top"><el-form-item label="规则名称"><el-input v-model.trim="ruleForm.name" maxlength="100" /></el-form-item><div class="commercial-form-grid"><el-form-item label="运算符"><el-select v-model="ruleForm.operator"><el-option label="大于" value="GT"/><el-option label="大于等于" value="GTE"/><el-option label="小于" value="LT"/><el-option label="小于等于" value="LTE"/><el-option label="等于" value="EQ"/></el-select></el-form-item><el-form-item label="阈值"><el-input-number v-model="ruleForm.threshold" :controls="false" style="width:100%" /></el-form-item><el-form-item label="抑制窗口（秒）"><el-input-number v-model="ruleForm.suppressionSeconds" :min="0" :max="86400" style="width:100%" /></el-form-item><el-form-item label="工作空间"><el-select v-model="ruleForm.workspaceId"><el-option v-for="workspace in app.workspaces" :key="workspace.id" :label="workspace.workspaceName" :value="workspace.id" /></el-select></el-form-item></div><el-form-item label="通知成员"><el-select v-model="ruleForm.recipients" multiple filterable style="width:100%"><el-option v-for="member in activeMembers" :key="member.id" :label="member.memberName" :value="member.id" /></el-select></el-form-item></el-form><template #footer><el-button @click="ruleOpen=false">取消</el-button><el-button type="primary" :loading="saving" :disabled="!ruleForm.name||!ruleForm.recipients.length" @click="saveRule">保存</el-button></template></CommonDialog>
    <el-drawer v-model="eventOpen" title="告警事件详情" size="520px"><template v-if="selectedEvent"><div class="commercial-detail-heading"><div><h3>{{ruleName(selectedEvent.ruleId)}}</h3><p>事件 ID {{selectedEvent.id}} · {{formatTime(selectedEvent.occurredAt)}}</p></div><el-tag :type="eventTone(selectedEvent.status)">{{eventLabel(selectedEvent.status)}}</el-tag></div><dl class="commercial-detail-list"><div><dt>实际值</dt><dd>{{selectedEvent.actualValue}}</dd></div><div><dt>去重键</dt><dd>{{selectedEvent.dedupeKey}}</dd></div><div><dt>恢复状态</dt><dd>{{selectedEvent.status==='RECOVERED'?'服务端已确认恢复':'尚未恢复或无需恢复'}}</dd></div></dl><h4>证据快照</h4><pre class="commercial-evidence">{{JSON.stringify(selectedEvent.evidence,null,2)}}</pre><el-button v-if="selectedEvent.status==='OPEN'" type="primary" style="width:100%" @click="ack(selectedEvent)">确认告警</el-button></template></el-drawer>
  </div>
</template>

<script setup lang="ts">
import type { Id } from '../api/resource-id'
import { resourceId } from '../api/resource-id'
import { computed, ref, watch } from 'vue'
import { ElMessage } from 'element-plus'
import CommonDialog from '../components/common/CommonDialog.vue'; import UnifiedState from '../components/common/UnifiedState.vue'
import { commercialApi, organizationApi } from '../api/runtime'; import type { AlertEvent, AlertRule } from '../commercial/types'; import type { MemberContext } from '../auth/types'; import { useAppStore } from '../stores/app'
import { useConfirm } from '../composables/useConfirm'
const app=useAppStore(); const rules=ref<AlertRule[]>([]); const events=ref<AlertEvent[]>([]); const members=ref<MemberContext[]>([]); const loading=ref(true); const error=ref(''); const tab=ref<'rules'|'events'>('rules'); const ruleOpen=ref(false); const editingRule=ref<AlertRule>(); const saving=ref(false); const eventOpen=ref(false); const selectedEvent=ref<AlertEvent>();
const { confirm } = useConfirm()
const ruleForm=ref({name:'',operator:'GT',threshold:0,suppressionSeconds:600,workspaceId:app.workspaceId,recipients:[] as Id[]}); const activeMembers=computed(()=>members.value.filter(item=>item.memberStatus==='ACTIVE'))
async function load(){loading.value=true;error.value='';try{[rules.value,events.value,members.value]=await Promise.all([commercialApi.alertRules(),commercialApi.alertEvents(),organizationApi.members(resourceId(app.tenantId))])}catch(e){error.value=e instanceof Error?e.message:'告警数据加载失败'}finally{loading.value=false}}
function newRule(){editingRule.value=undefined;ruleForm.value={name:'',operator:'GT',threshold:0,suppressionSeconds:600,workspaceId:app.workspaceId,recipients:[]};ruleOpen.value=true}
function editRule(row:AlertRule){editingRule.value=row;ruleForm.value={name:row.name,operator:row.operator,threshold:row.threshold,suppressionSeconds:row.suppressionSeconds,workspaceId:row.workspaceId,recipients:[...row.recipients]};ruleOpen.value=true}
async function saveRule(){saving.value=true;try{if(editingRule.value){const updated=await commercialApi.updateAlertRule(editingRule.value.id,ruleForm.value);rules.value[rules.value.findIndex(item=>item.id===updated.id)]=updated}else{rules.value.push(await commercialApi.createAlertRule(ruleForm.value))}ruleOpen.value=false;ElMessage.success('告警规则已保存')}finally{saving.value=false}}
async function toggleRule(row:AlertRule){const next=row.status==='ACTIVE'?'DISABLED':'ACTIVE';if(!await confirm(`${next==='DISABLED'?'停用':'启用'}“${row.name}”后，${next==='DISABLED'?'将停止后续阈值评估和通知':'新的评估周期将重新产生告警'}。`,{title:`${next==='DISABLED'?'停用':'启用'}告警规则`,confirmText:'确认',danger:next==='DISABLED'}))return;const updated=await commercialApi.updateAlertRule(row.id,{status:next});rules.value[rules.value.findIndex(item=>item.id===row.id)]=updated}
function showEvent(row:AlertEvent){selectedEvent.value=row;eventOpen.value=true} async function ack(row:AlertEvent){if(!await confirm(`确认告警事件 #${row.id}？此操作仅表示已知悉，不会自动恢复业务指标。`,{title:'确认告警',confirmText:'已知悉'}))return;const updated=await commercialApi.acknowledgeAlert(row.id);events.value[events.value.findIndex(item=>item.id===row.id)]=updated;selectedEvent.value=updated;ElMessage.success('告警已由服务端记录为已确认')}
function memberName(id:Id){return members.value.find(item=>item.id===id)?.memberName??`成员 ${id}`} function ruleName(id:Id){return rules.value.find(item=>item.id===id)?.name??`规则 ${id}`} function operatorLabel(v:string){return({GT:'大于',GTE:'大于等于',LT:'小于',LTE:'小于等于',EQ:'等于'} as Record<string,string>)[v]??v} function eventLabel(v:string){return({OPEN:'待处理',ACKNOWLEDGED:'已确认',SUPPRESSED:'已抑制',RECOVERED:'已恢复'} as Record<string,string>)[v]??v} function eventTone(v:string):'success'|'warning'|'danger'|'info'{return v==='OPEN'?'danger':v==='RECOVERED'?'success':v==='SUPPRESSED'?'info':'warning'} function formatDuration(s:number){return s>=3600?`${s/3600} 小时`:s>=60?`${s/60} 分钟`:`${s} 秒`} function formatTime(v:string){return new Intl.DateTimeFormat('zh-CN',{dateStyle:'medium',timeStyle:'short'}).format(new Date(v))}
watch(()=>app.contextVersion,()=>void load());void load()
</script>
